import Link from 'next/link';
import { notFound, redirect } from 'next/navigation';
import { createClient } from '@/lib/supabase/server';
import { createAdminClient } from '@/lib/supabase/admin';

function dateTime(value:string){return new Intl.DateTimeFormat('nb-NO',{dateStyle:'medium',timeStyle:'short',timeZone:'Europe/Oslo'}).format(new Date(value));}

export default async function ExternalClientHistoryPage({params}:{params:Promise<{id:string}>}){
  const {id}=await params; const supabase=await createClient(); const {data:{user}}=await supabase.auth.getUser(); if(!user) redirect(`/login?next=${encodeURIComponent(`/trainer-dashboard/clients/external/${id}`)}`);
  const admin=createAdminClient(); const {data:client}=await admin.from('trainer_clients').select('*').eq('id',id).eq('trainer_id',user.id).maybeSingle(); if(!client) notFound();
  const [{data:dogs},{data:appointments},{data:journals},{data:manualSeats}]=await Promise.all([
    admin.from('trainer_client_dogs').select('*').eq('trainer_id',user.id).eq('client_id',id).order('name'),
    admin.from('external_appointments').select('*').eq('trainer_id',user.id).eq('client_id',id).order('starts_at',{ascending:false}),
    admin.from('trainer_lesson_journals').select('*').eq('trainer_id',user.id).eq('trainer_client_id',id).order('occurred_at',{ascending:false}),
    admin.from('group_manual_participants').select('id,offering_id,dog_name,status,price_nok,created_at').eq('trainer_id',user.id).eq('client_id',id).order('created_at',{ascending:false}),
  ]);
  const offeringIds=[...new Set((manualSeats||[]).map(s=>s.offering_id))]; const {data:offerings}=offeringIds.length?await admin.from('group_offerings').select('id,title').in('id',offeringIds):{data:[] as any[]}; const offeringMap=new Map((offerings||[]).map(o=>[o.id,o.title]));
  const journalIds=(journals||[]).map(j=>j.id); const {data:shared}=journalIds.length?await admin.from('lesson_shared_notes').select('*').in('journal_id',journalIds):{data:[] as any[]}; const journalByAppointment=new Map((journals||[]).filter(j=>j.external_appointment_id).map(j=>[j.external_appointment_id,j])); const sharedByJournal=new Map((shared||[]).map(s=>[s.journal_id,s])); const dogMap=new Map((dogs||[]).map(d=>[d.id,d]));
  return <main className="dashboard client-history-page"><Link className="back-link" href="/trainer-dashboard/clients">← Til kunderegister</Link><section className="dashboard-heading"><div><span className="eyebrow">Ekstern kunde</span><h1>{client.name}</h1><p className="muted">{[client.email,client.phone].filter(Boolean).join(' · ')||'Ingen kontaktinformasjon'}</p>{client.notes?<p>{client.notes}</p>:null}</div><Link className="btn" href="/trainer-dashboard/calendar#new-appointment">+ Ny avtale</Link></section>
  <section className="dashboard-section"><div className="section-title"><div><span className="eyebrow">Hunder</span><h2>{dogs?.length||0} registrert</h2></div></div>{dogs?.length?<div className="trainer-client-grid">{dogs.map(d=><article className="trainer-client-card" key={d.id}><h3>🐕 {d.name}</h3><p className="muted">{d.breed||'Rase ikke oppgitt'}</p>{d.notes?<p>{d.notes}</p>:null}</article>)}</div>:<p className="muted">Ingen hunder registrert.</p>}</section>
  <section className="dashboard-section"><div className="section-title"><div><span className="eyebrow">Privattimer</span><h2>Journal og avtalehistorikk</h2></div></div>{appointments?.length?<div className="journal-timeline">{appointments.map(a=>{const journal=journalByAppointment.get(a.id);const share=journal?sharedByJournal.get(journal.id):null;const dog=a.dog_id?dogMap.get(a.dog_id):null;return <article className="journal-timeline-card" key={a.id}><div className="journal-timeline-date"><strong>{dateTime(a.starts_at)}</strong><span>{a.title} · {dog?.name||'Hund'}</span></div><div className="journal-timeline-body">{journal?.goals?<p><strong>Jobbet med:</strong> {journal.goals}</p>:null}{journal?.private_notes?<p className="journal-private-preview"><strong>Privat notat:</strong> {journal.private_notes}</p>:null}{share?.homework?<p><strong>Hjemmeoppgave:</strong> {share.homework}</p>:null}{!journal?<p className="muted">Ingen journal skrevet ennå.</p>:null}</div><Link className="btn secondary compact" href={`/trainer-dashboard/journal/external/${a.id}`}>{journal?'Åpne journal':'Skriv journal'}</Link></article>})}</div>:<p className="muted">Ingen privattimer registrert.</p>}</section>
  {manualSeats?.length?<section className="dashboard-section"><div className="section-title"><div><span className="eyebrow">Gruppeaktivitet</span><h2>Kurs og arrangementer</h2></div></div><div className="booking-list">{manualSeats.map(s=><article className="booking-row simple-booking-row" key={s.id}><div><strong>{offeringMap.get(s.offering_id)||'Kurs/arrangement'}</strong><span>{s.dog_name} · {s.status}</span></div><div>{s.price_nok} kr</div></article>)}</div></section>:null}</main>;
}
